using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class SurfaceSetRotationCheck
{
 static void Reject(Action a,string why){bool rejected=false;try{a();}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException(why);}
 internal static int Run(string input,string output){var rows=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray();int cases=0;
 foreach(var row in rows){string fault=row!["fault"]!.GetValue<string>();if(fault=="source_nonunit")continue;string root=row["root"]!.GetValue<string>(),id=row["executionId"]!.GetValue<string>(),sha=row["executionSha256"]!.GetValue<string>();if(fault is "control"or"control_oblique"){
  _=SurfaceSetTranslationProof.Execution(root,id,sha,true,false,true);var v=SolidQuarterTurnProof.Raw(root,row["verificationId"]!.GetValue<string>(),row["verificationSha256"]!.GetValue<string>()).Value;SurfaceSetTranslationProof.Verified(root,v,row["verificationArguments"]!.AsObject(),false,true);Reject(()=>SurfaceSetTranslationProof.Execution(root,id,sha,true,true),"Translation verifier admitted rotation schema9");cases+=3;
 }else if(fault=="execute_only"){var x=SolidQuarterTurnProof.Raw(root,id,sha).Value;SurfaceSetTranslationProof.Receipt(root,x,row["arguments"]!.AsObject(),false,true);cases++;}
 else{Reject(()=>SurfaceSetTranslationProof.Execution(root,id,sha,false,false,true),"SDK admitted partial/tampered set rotation "+fault);cases++;}}
 var control=rows.Single(r=>r!["fault"]!.GetValue<string>()=="control_oblique")!.AsObject();string cr=control["root"]!.GetValue<string>();var plan=SurfaceSetTranslationProof.Execution(cr,control["executionId"]!.GetValue<string>(),control["executionSha256"]!.GetValue<string>(),true,false,true);var before=ArtifactProof.Verified(cr,"responses",plan["inspectionRequestId"]!.GetValue<string>(),plan["inspectionSha256"]!.GetValue<string>(),16000000);var after=ArtifactProof.Verified(cr,"responses",control["verificationArguments"]!["inspectionRequestId"]!.GetValue<string>(),control["verificationArguments"]!["inspectionSha256"]!.GetValue<string>(),16000000);var vraw=SolidQuarterTurnProof.Raw(cr,control["verificationId"]!.GetValue<string>()).Value;
 foreach(var fault in new[]{"target_normal","nontarget_ulp","visibility","target_position","zero_normal"}){var changed=vraw["surfaceCaptureAfter"]!.DeepClone().AsObject();if(fault=="visibility")changed["witnesses"]![0]!["samples"]!["visibility"]![0]=false;else if(fault=="target_position")changed["witnesses"]![0]!["samples"]!["positionsWorldRaw"]![0]![0]=999;else if(fault=="zero_normal")changed["witnesses"]![0]!["samples"]!["normalsWorldRaw"]![0]=new JsonArray(0,0,0);else changed["witnesses"]![fault=="nontarget_ulp"?2:0]!["samples"]!["normalsWorldRaw"]![0]![0]=fault=="nontarget_ulp"?2.220446049250313e-16:0.3;Reject(()=>SurfaceSetTranslationProof.Post(before,after,plan["captureBefore"]!.AsObject(),changed,new JsonArray(0,0,0),SurfaceSetTranslationProof.Keys(plan),false,plan),"SDK admitted rotation witness fault "+fault);cases++;}
 Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: {cases} Framework/SDK set-rotation/steps/normal/partial/fence proofs; no CAD.");return 0;}
}
